        * { box-sizing:border-box; } html { scroll-behavior:smooth; } body { margin:0; background:var(--paper); color:var(--ink); font:500 14px/1.5 Manrope, sans-serif; } button,input,select { font:inherit; } button { cursor:pointer; } a { color:inherit; text-decoration:none; }
