        .hero { margin:22px auto 0; min-height:622px; max-width:1370px; border-radius:20px; overflow:hidden; position:relative; color:white; background:#0d251c; }.hero-photo { position:absolute; inset:0; background-image:linear-gradient(90deg,rgba(6,18,13,.92) 1%,rgba(6,18,13,.58) 41%,rgba(6,18,13,.08) 75%),url('https://legacymedia.sportsplatform.io/image/upload/v1670098871/ippg3ltsfswdh5sjltsx.jpg'); background-position:center; background-size:cover; transition:transform 1s ease; }.hero:hover .hero-photo { transform:scale(1.03); }.hero-content { position:relative; z-index:1; height:622px; width:min(620px,100%); padding:100px 7.4%; display:flex; flex-direction:column; align-items:flex-start; }.hero h1 { margin:13px 0 24px; font:700 clamp(56px,7vw,104px)/.91 Oswald,sans-serif; letter-spacing:-.025em; text-transform:uppercase; }.hero h1 em { color:var(--lime); font-style:normal; }.hero p { max-width:400px; font-size:15px; color:#e2ebe4; }.btn { border:0; border-radius:3px; padding:14px 20px; display:inline-flex; align-items:center; gap:12px; font-size:12px; font-weight:800; transition:.2s ease; }.btn-primary { background:var(--lime); color:var(--ink); }.btn-primary:hover { background:white; transform:translateY(-2px); }.btn-dark { background:var(--ink); color:white; }.btn-outline { background:transparent; border:1px solid #aeb8af; color:white; }.hero-actions { display:flex; gap:10px; margin-top:27px; }.hero-stats { position:absolute; z-index:2; right:32px; bottom:30px; display:flex; gap:1px; }.hero-stat { min-width:130px; padding:16px; background:rgba(10,22,15,.65); backdrop-filter:blur(10px); border-left:1px solid rgba(255,255,255,.25); }.hero-stat strong { display:block; font:600 25px/1 Oswald,sans-serif; color:var(--lime); }.hero-stat span { font-size:10px; color:#d8e2da; }
        .featured-strip { max-width:1310px; margin:0 auto; position:relative; z-index:3; margin-top:-42px; display:grid; grid-template-columns:repeat(3,1fr); box-shadow:0 18px 35px rgba(4,24,13,.16); }.feature { display:flex; gap:13px; align-items:center; padding:19px 24px; background:white; border-right:1px solid var(--line); }.feature:last-child { border:0; }.feature-icon { width:36px; height:36px; border-radius:50%; display:grid; place-items:center; background:#e9f1df; color:#30522c; }.feature b { display:block; font-size:12px; }.feature span { color:var(--muted); font-size:11px; }
        section { padding:105px 0 0; }.section-head { display:flex; justify-content:space-between; align-items:end; margin-bottom:28px; }.section-head h2 { margin:8px 0 0; font:600 46px/.98 Oswald,sans-serif; text-transform:uppercase; letter-spacing:-.02em; }.link-arrow { display:flex; gap:9px; align-items:center; font-weight:800; font-size:12px; }.link-arrow:hover { color:#588822; }.categories { display:grid; grid-template-columns:1.15fr 1fr 1fr 1fr; gap:14px; }.category { min-height:250px; padding:20px; position:relative; overflow:hidden; border-radius:13px; background:#dfe7d8; color:white; display:flex; align-items:flex-end; }.category.large { min-height:420px; grid-row:span 2; }.category:before { content:""; position:absolute; inset:0; background:linear-gradient(0deg,rgba(3,16,8,.78),rgba(3,16,8,.03) 65%); z-index:1; }.category img { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; transition:transform .5s ease; }.category:hover img { transform:scale(1.06); }.category-info { position:relative; z-index:2; }.category-info b { display:block; font:600 30px/1 Oswald,sans-serif; text-transform:uppercase; }.category-info span { font:500 10px "DM Mono"; color:var(--lime); text-transform:uppercase; letter-spacing:.08em; }.category .round-arrow { position:absolute; z-index:2; top:18px; right:18px; background:rgba(255,255,255,.95); color:var(--ink); }
        .round-arrow { border:0; border-radius:50%; width:36px; height:36px; display:grid; place-items:center; }.products-toolbar { display:flex; align-items:center; gap:9px; margin-bottom:26px; }.filter-pill { border:1px solid var(--line); background:white; padding:9px 14px; border-radius:20px; font-weight:700; font-size:11px; }.filter-pill.active,.filter-pill:hover { border-color:var(--ink); background:var(--ink); color:white; }.products { display:grid; grid-template-columns:repeat(4,1fr); gap:17px; }.product { position:relative; min-width:0; }.product-visual { height:310px; overflow:hidden; position:relative; background:#e9eee8; border-radius:9px; }.product-visual img { width:100%; height:100%; object-fit:cover; transition:transform .45s ease; mix-blend-mode:multiply; }.product:hover .product-visual img { transform:scale(1.1); }.product-badge { position:absolute; z-index:2; top:12px; left:12px; border-radius:3px; padding:5px 7px; background:var(--lime); font:700 9px "DM Mono"; text-transform:uppercase; }.quick-add { position:absolute; bottom:12px; left:12px; right:12px; transform:translateY(65px); transition:.25s ease; }.product:hover .quick-add { transform:translateY(0); }.quick-add button { width:100%; border:0; padding:12px; border-radius:3px; background:var(--ink); color:white; font-size:11px; font-weight:800; }.wish { position:absolute; right:12px; top:12px; border:0; width:33px; height:33px; border-radius:50%; background:rgba(255,255,255,.9); }.wish.loved { color:var(--red); }.product-meta { padding:13px 3px; }.product-meta p { margin:0 0 5px; color:var(--muted); font:10px "DM Mono"; text-transform:uppercase; }.product-meta h3 { font-size:13px; margin:0 0 6px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }.price { font:700 13px "DM Mono"; }.old-price { color:#879087; text-decoration:line-through; font-weight:400; margin-left:5px; }.no-products { grid-column:1 / -1; text-align:center; padding:70px; border:1px dashed var(--line); color:var(--muted); }
        .campaign { margin-top:105px; background:var(--ink); color:white; overflow:hidden; position:relative; }.campaign .shell { min-height:500px; display:flex; align-items:center; position:relative; }.campaign-copy { width:48%; padding:65px 0; position:relative; z-index:2; }.campaign h2 { font:600 60px/.93 Oswald,sans-serif; text-transform:uppercase; margin:12px 0 20px; }.campaign h2 span { color:var(--lime); }.campaign p { color:#b8c8bd; max-width:390px; }.campaign-img { position:absolute; inset:0 0 0 48%; width:52%; height:100%; object-fit:cover; opacity:.86; filter:saturate(.8); }.campaign:after { content:""; position:absolute; inset:0; background:linear-gradient(90deg,var(--ink) 35%,rgba(7,17,13,.08) 72%); }.message { font:500 11px "DM Mono"; color:var(--lime); margin-top:13px; min-height:16px; }.journal-grid { display:grid; grid-template-columns:1.05fr 1fr 1fr; gap:18px; }.journal-card img { width:100%; height:270px; object-fit:cover; border-radius:8px; filter:grayscale(15%); }.journal-card:first-child img { height:360px; }.journal-card span { display:block; margin-top:14px; color:#60715f; font:10px "DM Mono"; text-transform:uppercase; }.journal-card h3 { margin:6px 0; font:600 22px/1.15 Oswald,sans-serif; text-transform:uppercase; }.footer { margin-top:100px; background:#dbe5d1; padding:60px 0 30px; }.newsletter { display:flex; justify-content:space-between; align-items:end; gap:30px; padding-bottom:48px; border-bottom:1px solid #bfcdb8; }.newsletter h2 { margin:5px 0; font:600 46px/.98 Oswald,sans-serif; text-transform:uppercase; }.newsletter-form { width:390px; display:flex; border-bottom:1px solid var(--ink); padding-bottom:9px; }.newsletter-form input { flex:1; border:0; outline:0; background:transparent; }.newsletter-form button { border:0; background:transparent; font-weight:800; }.footer-bottom { padding-top:28px; display:flex; justify-content:space-between; font:10px "DM Mono"; color:#62715f; }
        .drawer-backdrop,.modal-backdrop { position:fixed; inset:0; background:rgba(3,13,8,.5); backdrop-filter:blur(4px); z-index:10; opacity:0; visibility:hidden; transition:.25s; }.drawer-backdrop.show,.modal-backdrop.show { opacity:1; visibility:visible; }.cart-drawer { position:fixed; z-index:11; top:0; right:0; height:100vh; width:min(440px,100vw); padding:24px; background:white; transform:translateX(105%); transition:.33s cubic-bezier(.2,.8,.2,1); display:flex; flex-direction:column; }.cart-drawer.show { transform:none; }.drawer-head { display:flex; justify-content:space-between; align-items:center; padding-bottom:20px; border-bottom:1px solid var(--line); }.drawer-head h2 { margin:0; font:600 27px Oswald,sans-serif; text-transform:uppercase; }.close { border:0; background:#eff3ed; width:35px; height:35px; border-radius:50%; font-size:20px; }.cart-lines { flex:1; overflow:auto; padding:16px 0; }.cart-empty { padding:65px 10px; text-align:center; color:var(--muted); }.cart-line { display:grid; grid-template-columns:78px 1fr auto; gap:12px; margin-bottom:17px; }.cart-line img { width:78px; height:78px; object-fit:cover; border-radius:5px; mix-blend-mode:multiply; background:#edf0eb; }.cart-line h4 { margin:0 0 5px; font-size:12px; }.cart-line p { margin:0 0 7px; color:var(--muted); font-size:10px; }.quantity { display:flex; align-items:center; width:max-content; border:1px solid var(--line); border-radius:3px; }.quantity button { width:24px; height:23px; border:0; background:white; }.quantity span { width:25px; text-align:center; font:11px "DM Mono"; }.delete-line { align-self:start; border:0; background:none; color:#899288; }.cart-foot { border-top:1px solid var(--line); padding-top:17px; }.coupon { display:flex; border:1px dashed #afbaae; border-radius:3px; padding:4px; margin:0 0 15px; }.coupon input { min-width:0; flex:1; padding:7px; border:0; outline:0; }.coupon button { border:0; background:var(--lime); padding:0 11px; font-weight:800; font-size:11px; }.total-row { display:flex; justify-content:space-between; margin:7px 0; }.total-row strong { font:700 17px "DM Mono"; }.checkout { width:100%; justify-content:center; margin-top:13px; }.toast { position:fixed; z-index:20; left:50%; bottom:25px; transform:translate(-50%,100px); transition:.3s; background:var(--ink); color:white; padding:13px 18px; border-radius:4px; font-size:12px; box-shadow:0 10px 30px rgba(0,0,0,.2); }.toast.show { transform:translate(-50%,0); }.product-modal { position:fixed; z-index:12; top:50%; left:50%; width:min(760px,calc(100vw - 28px)); max-height:90vh; overflow:auto; transform:translate(-50%,-47%); opacity:0; visibility:hidden; background:white; border-radius:12px; padding:22px; transition:.25s; }.product-modal.show { transform:translate(-50%,-50%); opacity:1; visibility:visible; }.modal-grid { display:grid; grid-template-columns:1fr 1fr; gap:30px; }.modal-img { height:410px; background:#edf0eb; overflow:hidden; border-radius:7px; cursor:zoom-in; }.modal-img img { width:100%; height:100%; object-fit:cover; mix-blend-mode:multiply; transition:transform .3s; }.modal-img:hover img { transform:scale(1.5); }.modal-info h2 { margin:7px 0 10px; font:600 32px/.98 Oswald,sans-serif; text-transform:uppercase; }.modal-price { font:700 19px "DM Mono"; }.choice-label { display:block; margin:23px 0 9px; font-size:10px; font-family:"DM Mono"; text-transform:uppercase; }.swatches,.sizes { display:flex; gap:8px; }.swatch { width:28px; height:28px; border-radius:50%; border:3px solid white; outline:1px solid var(--line); }.swatch.active { outline:2px solid var(--ink); }.size { width:40px; height:34px; border:1px solid var(--line); background:white; font-size:11px; }.size.active { border-color:var(--ink); background:var(--ink); color:white; }.modal-actions { display:flex; gap:9px; margin-top:26px; }.modal-actions .btn { flex:1; justify-content:center; }.modal-close { position:absolute; right:14px; top:14px; z-index:2; }
